from azure.identity import DefaultAzureCredential
from azure.keyvault.secrets import SecretClient

def get_secret_client(vault_url):
    credential = DefaultAzureCredential()
    return SecretClient(vault_url=vault_url, credential=credential)

import dataclasses
import typing

@dataclasses.dataclass
class SecretPayload:
    secret_name: str
    version_id: typing.Optional[str] = None
    key_field: typing.Optional[str] = None

@dataclasses.dataclass
class DbSecret:
    username: str
    password: str
    host: str
    port: typing.Optional[int] = None
    database: typing.Optional[str] = None

@dataclasses.dataclass
class ApiKeySecret:
    api_key: str

@dataclasses.dataclass
class SecretMetadata:
    secret_name: str
    version: str
    enabled: bool
    created_on: typing.Optional[typing.Any] = None # datetime object
    expires_on: typing.Optional[typing.Any] = None # datetime object
    tags: typing.Optional[typing.Dict[str, str]] = None

def secret_label_safety(payload):
    unsafe_keywords = ["password", "secret", "key", "credential", "token", "api_key", "connection_string"]
    unsafe_found = []

    labels = payload.get('labels', {})
    notes = payload.get('notes', "")
    secret_name = payload.get('secret_name', 'unknown')

    for key, value in labels.items():
        for keyword in unsafe_keywords:
            if keyword in key.lower() or keyword in value.lower():
                unsafe_found.append(f"Secret '{secret_name}': Unsafe keyword '{keyword}' found in label '{key}':'{value}'.")

    for keyword in unsafe_keywords:
        if keyword in notes.lower():
            unsafe_found.append(f"Secret '{secret_name}': Unsafe keyword '{keyword}' found in notes.")

    if not unsafe_found:
        return {'status': 'safe', 'message': f'Secret {secret_name}: No unsafe keywords found in labels or notes.'}
    else:
        return {'status': 'unsafe', 'message': f'Secret {secret_name}: Unsafe content detected.', 'details': unsafe_found}

import os
from openai import AzureOpenAI

def secret_audit_embedding(payload, config=None):
    config = config or {}
    audit_note = payload.get('audit_note', '')

    if not audit_note:
        return {'embedding': [], 'message': 'No audit note provided for embedding.'}

    # Azure OpenAI configuration
    # Ensure these environment variables are set:
    # AZURE_OPENAI_ENDPOINT, AZURE_OPENAI_API_KEY, AZURE_OPENAI_API_VERSION, AZURE_OPENAI_DEPLOYMENT_NAME (for embeddings)
    client = AzureOpenAI(
        azure_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT") or config.get('azure_openai_endpoint'),
        api_key = os.environ.get("AZURE_OPENAI_API_KEY") or config.get('azure_openai_api_key'),
        api_version = os.environ.get("AZURE_OPENAI_API_VERSION") or config.get('azure_openai_api_version', "2024-02-01"),
    )

    deployment_name = os.environ.get("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME") or config.get('azure_openai_embedding_deployment_name')
    if not deployment_name:
        return {'embedding': [], 'message': 'Azure OpenAI embedding deployment name not configured.'}

    try:
        response = client.embeddings.create(
            input=audit_note,
            model=deployment_name # deployment name is used as model name in Azure OpenAI
        )
        embedding = response.data[0].embedding
        return {'embedding': embedding, 'message': 'Audit note embedded successfully.'}
    except Exception as e:
        return {'embedding': [], 'message': f'Error generating embedding: {str(e)}'}

import os
import requests
import uuid

def runbook_translate(payload, config=None):
    config = config or {}
    text_to_translate = payload.get('text', '')
    target_language = payload.get('target_language', 'en')

    if not text_to_translate:
        return {'translated_text': '', 'message': 'No text provided for translation.'}

    # Azure Translator Text API configuration
    # Ensure these environment variables are set:
    # AZURE_TRANSLATOR_TEXT_ENDPOINT, AZURE_TRANSLATOR_TEXT_SUBSCRIPTION_KEY, AZURE_TRANSLATOR_TEXT_REGION
    endpoint = os.environ.get("AZURE_TRANSLATOR_TEXT_ENDPOINT") or config.get('azure_translator_text_endpoint')
    subscription_key = os.environ.get("AZURE_TRANSLATOR_TEXT_SUBSCRIPTION_KEY") or config.get('azure_translator_text_subscription_key')
    region = os.environ.get("AZURE_TRANSLATOR_TEXT_REGION") or config.get('azure_translator_text_region')

    if not all([endpoint, subscription_key, region]):
        return {'translated_text': '', 'message': 'Azure Translator Text API configuration missing.'}

    path = '/translate'
    constructed_url = endpoint + path

    params = {
        'api-version': '3.0',
        'to': target_language
    }

    headers = {
        'Ocp-Apim-Subscription-Key': subscription_key,
        'Ocp-Apim-Subscription-Region': region,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    body = [{
        'text': text_to_translate
    }]

    try:
        request = requests.post(constructed_url, params=params, headers=headers, json=body)
        response = request.json()

        if request.status_code == 200 and response and len(response) > 0 and 'translations' in response[0]:
            translated_text = response[0]['translations'][0]['text']
            return {'translated_text': translated_text, 'message': 'Text translated successfully.'}
        else:
            return {'translated_text': '', 'message': f'Error during translation: {response.get('error', {}).get('message', 'Unknown error')}'}
    except Exception as e:
        return {'translated_text': '', 'message': f'Exception during translation: {str(e)}'}
